import{_ as a,o as i,c as e,a0 as n}from"./chunks/framework.t4Rf69I2.js";const k=JSON.parse('{"title":"使用说明","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/usage.md","filePath":"zh/guide/usage.md","lastUpdated":1785233645000}'),t={name:"zh/guide/usage.md"};function l(p,s,h,d,o,c){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h1><p>go-cipher-cli 提供密码转密钥和 Diceware 助记口令生成两个核心功能，与 <a href="https://tools.wcheer.com/" target="_blank" rel="noreferrer">web 工具</a> 字节级互通。</p><h2 id="命令总览" tabindex="-1">命令总览 <a class="header-anchor" href="#命令总览" aria-label="Permalink to &quot;命令总览&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Available Commands:</span></span>
<span class="line"><span>  completion  Generate the autocompletion script for the specified shell</span></span>
<span class="line"><span>  diceware    生成 Diceware 助记口令（EFF 词表，7776 词）</span></span>
<span class="line"><span>  enhance     将密码转换为 256 位高熵密钥（密码转密钥）</span></span>
<span class="line"><span>  help        Help about any command</span></span>
<span class="line"><span>  version     Print the CLI version</span></span></code></pre></div><h2 id="版本号" tabindex="-1">版本号 <a class="header-anchor" href="#版本号" aria-label="Permalink to &quot;版本号&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输出: v0.3.1</span></span></code></pre></div><h2 id="密码转密钥-enhance" tabindex="-1">密码转密钥（enhance） <a class="header-anchor" href="#密码转密钥-enhance" aria-label="Permalink to &quot;密码转密钥（enhance）&quot;">​</a></h2><p>把你&quot;常用但可能不够强&quot;的密码，通过 Argon2id 慢函数加固，转换成 256 位高熵密钥。同一组密码 + 盐后缀<strong>确定性</strong>派生出相同的密钥，无法由密钥反推密码。</p><h3 id="算法流程" tabindex="-1">算法流程 <a class="header-anchor" href="#算法流程" aria-label="Permalink to &quot;算法流程&quot;">​</a></h3><ol><li><strong>Argon2id 慢函数抗爆破</strong>：以用户密码为输入，以「固定盐 + 用户盐后缀」为盐，参数 64MB / 3 轮迭代 / 1 路并行，输出 64 字节主密钥 (PRK)</li><li><strong>HKDF-Expand(SHA-256) 域分离</strong>：对 PRK 做纯 Expand，输出 32 字节（256 位）子密钥</li><li><strong>输出</strong>：64 位十六进制字符串，方便跨平台复制与对齐</li></ol><h3 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to &quot;基本用法&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 派生 256 位密钥</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyMaster@2024&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 不同盐后缀派生不同密钥（推荐做法）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyMaster@2024&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> google</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyMaster@2024&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firefox</span></span></code></pre></div><p>输出示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>算法:     Argon2id(64MB/3轮/1路并行) + HKDF-Expand(SHA-256)</span></span>
<span class="line"><span>Domain:   default-v1</span></span>
<span class="line"><span>盐后缀:   google</span></span>
<span class="line"><span>密钥(hex):     3aac7a86fd8c549020841738920154a05bcae6dd116c116a991144df33a440eb</span></span>
<span class="line"><span>密钥(base64):  oqx6hv2MVJAg...9E3zOkDr</span></span>
<span class="line"><span>密钥长度:      256 位 (256 bit)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>-p, --password</code></td><td>要转换的密码（必填）</td></tr><tr><td><code>-s, --salt-suffix</code></td><td>可选盐后缀（如站点名、设备名），不同后缀派生不同密钥</td></tr><tr><td><code>--domain</code></td><td>域标签（默认 <code>default-v1</code>，一般不修改）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">与 web 端互通</p><p>只要「密码 + 盐后缀」相同，CLI 和 <a href="https://tools.wcheer.com/" target="_blank" rel="noreferrer">web 工具</a> 会派生出完全相同的 256 位密钥。</p></div><div class="tip custom-block"><p class="custom-block-title">盐后缀的使用建议</p><p>为不同用途使用不同盐后缀（如 <code>google</code>、<code>firefox</code>），即可从同一密码派生出互不相同的密钥，避免&quot;一处泄露处处泄露&quot;。</p></div><h2 id="diceware-助记口令-diceware" tabindex="-1">Diceware 助记口令（diceware） <a class="header-anchor" href="#diceware-助记口令-diceware" aria-label="Permalink to &quot;Diceware 助记口令（diceware）&quot;">​</a></h2><p>用 EFF 大型词表（7776 词）和密码学安全随机掷骰，生成易记但高熵的口令。</p><h3 id="安全原理" tabindex="-1">安全原理 <a class="header-anchor" href="#安全原理" aria-label="Permalink to &quot;安全原理&quot;">​</a></h3><ul><li>随机源：<code>crypto/rand</code>（Go CSPRNG），采用拒绝采样消除模偏差</li><li>每词提供约 <strong>12.9 bit</strong> 信息熵： <ul><li>5 词 → ~64.6 bit</li><li>6 词 → ~77.5 bit</li><li>8 词 → ~103.4 bit</li></ul></li><li>可能组合数 = 7776^词数（5 词约为 2.8×10^19）</li></ul><h3 id="基本用法-1" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法-1" aria-label="Permalink to &quot;基本用法&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 默认 5 词，无分隔符</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diceware</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 指定词数和分隔符</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diceware</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hyphen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diceware</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none</span></span></code></pre></div><p>输出示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>口令:         cavity-puppy-lego-vanquish-sediment</span></span>
<span class="line"><span>长度:         35 字符</span></span>
<span class="line"><span>词数:         5</span></span>
<span class="line"><span>信息熵:       64.62 bit</span></span>
<span class="line"><span>可能组合数:   2.84 × 10^19</span></span>
<span class="line"><span>分隔符:       连字符 (-)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>逐词掷骰详情:</span></span>
<span class="line"><span>   1. [15264] cavity</span></span>
<span class="line"><span>   2. [45662] puppy</span></span>
<span class="line"><span>   3. [35656] lego</span></span>
<span class="line"><span>   4. [65415] vanquish</span></span>
<span class="line"><span>   5. [53443] sediment</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>-n, --num-words</code></td><td>单词数量（1-20，默认 5）</td></tr><tr><td><code>--sep</code></td><td>分隔符：<code>space</code>（空格）/ <code>hyphen</code>（连字符） / <code>none</code>（无），默认 <code>none</code></td></tr></tbody></table><h2 id="全局参数" tabindex="-1">全局参数 <a class="header-anchor" href="#全局参数" aria-label="Permalink to &quot;全局参数&quot;">​</a></h2><h3 id="指定配置文件" tabindex="-1">指定配置文件 <a class="header-anchor" href="#指定配置文件" aria-label="Permalink to &quot;指定配置文件&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/config.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>支持的配置格式：YAML / JSON / TOML 等（由 Viper 自动识别扩展名）。</p><p>若未指定 <code>--config</code>，将按以下顺序查找名为 <code>config</code> 的文件：</p><ol><li>当前目录 <code>.</code></li><li><code>$HOME/.go-cipher-cli/</code></li></ol><p>示例 <code>config.yaml</code>：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">info</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # debug | info | warn | error</span></span></code></pre></div><h3 id="设置日志级别" tabindex="-1">设置日志级别 <a class="header-anchor" href="#设置日志级别" aria-label="Permalink to &quot;设置日志级别&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diceware</span></span></code></pre></div><p>可选值：<code>debug</code> / <code>info</code> / <code>warn</code> / <code>error</code>，默认 <code>info</code>。</p><div class="tip custom-block"><p class="custom-block-title">环境变量</p><p>所有配置项均可通过环境变量覆盖，前缀为 <code>GOCIPHER_</code>，<code>.</code> 替换为 <code>_</code>。 例如 <code>log.level</code> 对应环境变量 <code>GOCIPHER_LOG_LEVEL</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GOCIPHER_LOG_LEVEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">warn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div></div><h2 id="退出码" tabindex="-1">退出码 <a class="header-anchor" href="#退出码" aria-label="Permalink to &quot;退出码&quot;">​</a></h2><table tabindex="0"><thead><tr><th>退出码</th><th>含义</th></tr></thead><tbody><tr><td><code>0</code></td><td>成功</td></tr><tr><td><code>1</code></td><td>执行出错（如配置加载失败、命令返回错误）</td></tr></tbody></table>`,41)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
